WITH exploded AS (SELECT id, code FROM carts LATERAL VIEW EXPLODE(coupon_codes) x AS code), cleaned AS (SELECT *, CASE WHEN code = 'SPRING10' THEN 1 ELSE 0 END AS is_spring10, COALESCE(code, 'UNKNOWN') AS code_filled FROM exploded WHERE code IS NOT NULL AND code IS DISTINCT FROM 'VIP'), cleaned_carts AS (SELECT *, FLOOR(is_spring10) AS is_spring10_whole, ROUND(is_spring10 * 100, 2) AS is_spring10_adjusted FROM cleaned WHERE code IS NOT NULL), with_windows AS (SELECT id, code, code_filled, is_spring10_adjusted, RANK() OVER (PARTITION BY code ORDER BY is_spring10 NULLS LAST) AS is_spring10_rank, MIN(is_spring10_whole) OVER (PARTITION BY code) AS code_min_is_spring10_whole, COUNT(is_spring10_whole) OVER (PARTITION BY code) AS code_count_is_spring10_whole FROM cleaned_carts), with_windows_carts AS (SELECT *, SUM(is_spring10_rank) OVER (PARTITION BY code) AS code_sum_is_spring10_rank FROM with_windows) SELECT code, CASE WHEN code_min_is_spring10_whole >= 86 THEN 'PREMIUM' ELSE 'STANDARD' END AS code_min_is_spring10_whole_tier, PERCENTILE_APPROX(code_count_is_spring10_whole, ARRAY(0.25, 0.5, 0.75)) AS code_count_is_spring10_whole_quartiles, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(code_min_is_spring10_whole, ARRAY(0.25, 0.5, 0.75)) AS code_min_is_spring10_whole_quartiles, GROUPING(code) AS gid FROM with_windows_carts GROUP BY GROUPING SETS ((code, CASE WHEN code_min_is_spring10_whole >= 86 THEN 'PREMIUM' ELSE 'STANDARD' END), (code)) HAVING COUNT(DISTINCT id) < 1000
